#!/bin/sh$
set -e$
python3 scripts/run_checks.py$

function.arguments:
{"command":"cd /testbed && grep -rn ' $' --include='*.py' . ; grep -rnP '\t' --include='*.py' . ; echo "no-ws-check-done"; for f in $(find . -name '*.py' -not -path './.git/*'); do python3 - "$f" <<'EOF'
import sys
p=sys.argv[1]
for i,l in enumerate(open(p,encoding='utf-8'),1):
    if l.rstrip('\n')!=l.rstrip(): print(p,i,repr(l))
EOF
done; echo done"}

{"command":"cd /testbed && pre-commit validate-config .pre-commit-config.yaml && echo "config OK"; pre-commit run --all-files -v 2>&1 | tail -6; echo "rerun-exit=${PIPESTATUS[0]}"; python3 -c "
import sqlite3,os
db=os.path.expanduser('~/.cache/pre-commit/db.db')
c=sqlite3.connect(db)
for r in c.execute('select * from repos'): print(r)
"; echo "=== final ==="; cat .checks/report.txt; ls -l .git/hooks/pre-commit; git status --porcelain | wc -l"}
